        SecretProtection.Configure(new TestProtector());var settings=new PetSettings{UiLanguage=language??"en_US",AutoUpdate=false,GreetingEnabled=false,ReadReplies=false,OnboardingState="completed",Wander=false,FollowCursor=false,HideOnFullscreen=false,SelectedCompanionKey=reloaded.PickerKey};foreach(var key in settings.Hotkeys.Keys.ToArray())settings.Hotkeys[key]="";new SettingsStore(Path.Combine(directory,"settings.json")).Save(settings);
