        var now=RelationshipTime.Current();for(int day=8;day>=2;day--){var t=new RelationshipTime(now.UtcNow.AddDays(-day),now.LocalOffset);Record(RelationshipEventType.Visit,"v"+day,t);Record(RelationshipEventType.SuccessfulWorkTask,"wa"+day,t);Record(RelationshipEventType.SuccessfulWorkTask,"wb"+day,t);}var yesterday=new RelationshipTime(now.UtcNow.AddDays(-1),now.LocalOffset);Record(RelationshipEventType.SuccessfulWorkTask,"ya",yesterday);if(crossing){Record(RelationshipEventType.CompletedConversation,"yc",yesterday);Record(RelationshipEventType.UserInteraction,"yi",yesterday);}else Record(RelationshipEventType.SuccessfulWorkTask,"yb",yesterday);
