            Check(!HasReply(),"pending pre-fullscreen interaction response is discarded after restore");Notice()?.Close();
            using(new RelationshipStore(directory).Acquire()){int priorRevision=Revision();owner.Pet.UserInteract("sleeping");Check(Revision()>priorRevision&&Playback().Action=="sleeping"&&Playback().Clip.Loop&&!owner.Relationships.FlushAsync().IsCompleted,"visible slow comparison is another admitted looping action");Fullscreen(false);Pause(1200);Fullscreen(false);}
            Complete(owner.Relationships.FlushAsync());AwaitReply(2000);State("after-visible-flush");Check(HasReply(),"unchanged visible policy and periodic probes retain current slow looping-action response");
            return count;
        }
        var maintenance=owner.DataMaintenance.BeginAsync();Complete(maintenance);using(maintenance.Result){owner.Pet.UserInteract("petting");Pause(500);Check(Notice()==null,"actual native maintenance refusal produces no stage response");}Check(owner.RelationshipService.GetSnapshot(owner.RelationshipCompanionId).State.Score==(crossing?79:80),"native refused interaction adds no points");
        owner.Pet.UserInteract("petting");Complete(owner.Relationships.FlushAsync());Pause(700);Check(owner.RelationshipService.GetSnapshot(owner.RelationshipCompanionId).State.Score==(crossing?80:81),"actual native petting gives exact81");var notice=Notice()!;
        Check(notice!=null&&notice.IsVisible&&notice.GetLogicalDescendants().OfType<TextBlock>().Count(t=>t.Text==reply)==1,"actual native petting displays unique imported stage reply once");
        Check(notice.GetLogicalDescendants().OfType<TextBlock>().Any(t=>t.Text==TextResources.Format("relationship.feedback.gain",1)),"native reply retains +1 after400ms");Check(!notice.ShowActivated&&!notice.ShowInTaskbar,"native unified notice remains passive");
        var evidence=Path.GetFullPath(Path.Combine("work","relationship-experience","native-"+Guid.NewGuid().ToString("N")));Directory.CreateDirectory(evidence);
        void Capture(RelationshipFeedbackWindow window,string name){Dispatcher.UIThread.RunJobs();AvaloniaHeadlessPlatform.ForceRenderTimerTick();using(var picture=window.CaptureRenderedFrame())picture!.Save(Path.Combine(evidence,name+"-framebuffer.png"),new PngBitmapEncoderOptions());using(var surface=new RenderTargetBitmap(new Avalonia.PixelSize((int)Math.Ceiling(window.Bounds.Width),(int)Math.Ceiling(window.Bounds.Height)))){surface.Render(window);surface.Save(Path.Combine(evidence,name+".png"),new PngBitmapEncoderOptions());}}
        Capture(notice,"response-and-gain");if(crossing){var milestone=owner.RelationshipService.GetSnapshot(owner.RelationshipCompanionId).State.Milestones.Single(m=>m.StageId=="familiar");Check(notice.GetLogicalDescendants().OfType<TextBlock>().Any(t=>t.Text==RelationshipContent.StageName("familiar"))&&notice.GetLogicalDescendants().OfType<TextBlock>().Any(t=>t.Text==RelationshipCardData.FormatDate(milestone.EarnedLocalDate)),"actual native79 to80 preserves earned stage/date with reply and +1");Console.WriteLine("CROSSING_CAPTURE_ROOT "+evidence);return count;}Console.WriteLine("CAPTURE_ROOT "+evidence);notice.Close();owner.Pet.Interact("petting");Complete(owner.Relationships.FlushAsync());Pause(500);Check(owner.RelationshipService.GetSnapshot(owner.RelationshipCompanionId).State.Score==81&&Notice()==null,"automatic native action adds no response or points");
        foreach(bool responseFirst in new[]{true,false}){
            string token="native-composition-"+responseFirst;string full=new string('W',280);var gain=new RelationshipFeedbackNotice{CompanionId=owner.RelationshipCompanionId,AwardedPoints=1,Milestones=new List<RelationshipMilestone>{new RelationshipMilestone{StageId="familiar",EarnedLocalDate="2026-10-20"}}};gain.EventIds.Add(token);
            void Feedback()=>typeof(DesktopController).GetMethod("ShowRelationshipFeedback",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.Invoke(owner,new object[]{gain});
            if(responseFirst)owner.ShowRelationshipInteraction(gain.CompanionId,full,token);else Feedback();if(responseFirst)Feedback();else owner.ShowRelationshipInteraction(gain.CompanionId,full,token);Pause(450);var merged=Notice()!;
            Check(merged.GetLogicalDescendants().OfType<TextBlock>().Any(t=>t.Text==full)&&merged.GetLogicalDescendants().OfType<TextBlock>().Any(t=>t.Text==TextResources.Format("relationship.feedback.gain",1))&&merged.GetLogicalDescendants().OfType<TextBlock>().Any(t=>t.Text==RelationshipContent.StageName("familiar"))&&merged.GetLogicalDescendants().OfType<TextBlock>().Any(t=>t.Text==RelationshipCardData.FormatDate("2026-10-20")),"native callback orders preserve reply +1 stage/date: "+responseFirst);
            var response=merged.GetLogicalDescendants().OfType<TextBlock>().Single(t=>t.Name=="RelationshipInteraction");Check(Avalonia.Automation.AutomationProperties.GetName(response)==full&&((ScrollViewer)response.Parent!).Bounds.Height<=132.1,"native long response bounded with full accessible text");Capture(merged,"composition-"+responseFirst);merged.Close();Feedback();owner.ShowRelationshipInteraction(gain.CompanionId,full,token);Check(Notice()==null,"native manual dismissal prevents late gain/reply resurrection");
        }
